// To use the "only_show_shader_hardcoded_connections"
// checkbox, edit the #define below and
// paste in neuron segment IDs of your choosing.
// (Don't list more than a few hundred.)
// Only connections in which BOTH pre and post
// belong to these segments will be shown.

#define HARDCODED_SEGMENT_LIST 111, 222, 333

#uicontrol bool show_pre checkbox(default=true)
#uicontrol bool show_post_partners checkbox(default=false)
bool show_post = show_post_partners;

#uicontrol float pre_size slider(min=1.0, max=20.0, default=6.0)
#uicontrol float post_size slider(min=1.0, max=20.0, default=4.0)

#uicontrol vec3 pre_default color(default="red")
#uicontrol vec3 post_default color(default="blue")

#define acetylcholine_code 0
#define dopamine_code 1
#define gaba_code 2
#define glutamate_code 3
#define histamine_code 4
#define octopamine_code 5
#define serotonin_code 6
#define unknown_nt_code 7

#uicontrol bool color_by_neurotransmitter checkbox(default=true)

#uicontrol vec3 acetylcholine color(default="#1f77b4")
#uicontrol vec3 dopamine color(default="#ff7f0e")
#uicontrol vec3 gaba color(default="#2ca02c")
#uicontrol vec3 glutamate color(default="#d62728")
#uicontrol vec3 histamine color(default="#9467bd")
#uicontrol vec3 octopamine color(default="#8c564b")
#uicontrol vec3 serotonin color(default="#e377c2")
#uicontrol vec3 unknown_nt color(default="#7f7f7f")

#uicontrol bool color_by_nt_probability checkbox(default=false)
#uicontrol bool color_by_nt_confidence checkbox(default=false)

#uicontrol bool color_by_tbar_fanout checkbox(default=false)
#uicontrol float max_fanout_display slider(min=1.0, max=20.0, step=1.0, default=10.0)

#define unknown_compartment_code 0
#define axon_code 1
#define dendrite_code 2
#define linker_code 3
#define cell_body_fiber_code 4

#uicontrol bool color_by_compartment checkbox(default=true)

#uicontrol vec3 axon color(default="#1f77b4")
#uicontrol vec3 dendrite color(default="#ff7f0e")
#uicontrol vec3 linker color(default="#2ca02c")
#uicontrol vec3 cell_body_fiber color(default="#d62728")
#uicontrol vec3 unknown_compartment color(default="#7f7f7f")

#uicontrol int color_seed slider(min=0, max=4294967295, default=0);
#uicontrol bool color_by_neuropil checkbox(default=true)
#uicontrol bool color_by_optic_column checkbox(default=false)
#uicontrol bool color_by_optic_layer checkbox(default=false)
#uicontrol bool color_by_neuron_id checkbox(default=false)
#uicontrol bool hide_uncolored checkbox(default=true)

#ifndef HARDCODED_SEGMENT_LIST
  #define HARDCODED_SEGMENT_LIST 0
#endif

const int segment_list[] = int[](HARDCODED_SEGMENT_LIST);
#uicontrol bool only_show_shader_hardcoded_connections checkbox(default=false)


vec3 viridis(float t) {

    const vec3 c0 = vec3(0.2777273272234177, 0.005407344544966578, 0.3340998053353061);
    const vec3 c1 = vec3(0.1050930431085774, 1.404613529898575, 1.384590162594685);
    const vec3 c2 = vec3(-0.3308618287255563, 0.214847559468213, 0.09509516302823659);
    const vec3 c3 = vec3(-4.634230498983486, -5.799100973351585, -19.33244095627987);
    const vec3 c4 = vec3(6.228269936347081, 14.17993336680509, 56.69055260068105);
    const vec3 c5 = vec3(4.776384997670288, -13.74514537774601, -65.35303263337234);
    const vec3 c6 = vec3(-5.435455855934631, 4.645852612178535, 26.3124352495832);

    return c0+t*(c1+t*(c2+t*(c3+t*(c4+t*(c5+t*c6)))));
}

uint hash_function(uint state, uint value) {
    uint k1 = 0xcc9e2d51u;
    uint k2 = 0x1b873593u;

    value = value * k1;
    value = (value << 15) | (value >> 17);
    value = value * k2;
    state = state ^ value;
    state = (state << 13) | (state >> 19);
    state = state * 5u + 0xe6546b64u;

    return state;
}

vec3 hsv_to_rgb(float h, float s, float v) {
    h *= 6.0;
    float hue_index = floor(h);
    float remainder = h - hue_index;
    float val1 = v * (1.0 - s);
    float val2 = v * (1.0 - (s * remainder));
    float val3 = v * (1.0 - (s * (1.0 - remainder)));

    int hue_remainder = int(hue_index) % 6;

    if (hue_remainder == 0) {
        return vec3(v, val3, val1);
    } else if (hue_remainder == 1) {
        return vec3(val2, v, val1);
    } else if (hue_remainder == 2) {
        return vec3(val1, v, val3);
    } else if (hue_remainder == 3) {
        return vec3(val1, val2, v);
    } else if (hue_remainder == 4) {
        return vec3(val3, val1, v);
    } else { // hue_remainder == 5
        return vec3(v, val1, val2);
    }
}

vec3 color_from_segment_id(uint color_seed_, uint segment_id) {
    uint result = hash_function(color_seed_, segment_id);

    // We only support 32-bit segment IDs, so newvalue is always 0,
    // and (id >> 32) would be undefined behavior!
    // uint newvalue = id >> 32;

    uint newvalue = 0u;
    uint result2 = hash_function(result, newvalue);

    float c0 = float(result2 & 0xFFu) / 255.0;
    float c1 = float((result2 >> 8) & 0xFFu) / 255.0;

    float h = c0;
    float s = 0.5 + 0.5 * c1;
    float v = 1.0;

    return hsv_to_rgb(h, s, v);
}

vec3 get_color_for_id(uint id) {
    if (id == 0u) {
        if (hide_uncolored) {
            discard;
        }
        //setPointMarkerBorderWidth(0.2);
        vec3 white = vec3(1.0, 1.0, 1.0);
        return white;
    }
    else {
        return color_from_segment_id(uint(color_seed), id);
    }
}

vec3 get_nt_color() {
    vec3 pre_color;

    switch (int(prop_predicted_nt())) {
        case acetylcholine_code:
            pre_color = acetylcholine;
            break;
        case dopamine_code:
            pre_color = dopamine;
            break;
        case gaba_code:
            pre_color = gaba;
            break;
        case glutamate_code:
            pre_color = glutamate;
            break;
        case histamine_code:
            pre_color = histamine;
            break;
        case octopamine_code:
            pre_color = octopamine;
            break;
        case serotonin_code:
            pre_color = serotonin;
            break;
        case unknown_nt_code:
            pre_color = unknown_nt;
            break;
        default:
            pre_color = vec3(1.0, 1.0, 1.0);
            break;
    }
    return pre_color;
}

vec3 get_compartment_color(int compartment_code) {
    vec3 color;

    switch (compartment_code) {
        case axon_code:
            color = axon;
            break;
        case dendrite_code:
            color = dendrite;
            break;
        case linker_code:
            color = linker;
            break;
        case cell_body_fiber_code:
            color = cell_body_fiber;
            break;
        case unknown_compartment_code:
            color = unknown_compartment;
            break;
        default:
            color = vec3(1.0, 1.0, 1.0);
            break;
    }
    return color;
}

bool is_in_segment_list(uint value) {
    for (int i = 0; i < segment_list.length(); i++) {
        if (uint(segment_list[i]) == value) return true;
    }
    return false;
}

void main() {    
    vec3 pre_color = pre_default;
    vec3 post_color = post_default;

    if (only_show_shader_hardcoded_connections) {
        if (!is_in_segment_list(prop_body_pre_u32()) || !is_in_segment_list(prop_body_post_u32())) {
            discard;
        }
    }

    setLineColor(vec3(1.0, 1.0, 1.0));
    setEndpointMarkerColor(
        vec4(pre_color, 1.0), vec4(post_color, 1.0)
    );

    if (int(color_by_neurotransmitter) + 
        int(color_by_nt_probability) + 
        int(color_by_nt_confidence) + 
        int(color_by_tbar_fanout) + 
        int(color_by_compartment) + 
        int(color_by_neuropil) + 
        int(color_by_optic_column) + 
        int(color_by_optic_layer) + 
        int(color_by_neuron_id)
    > 1) {
        // Invalid selection.
        discard;
    }
    else if (color_by_neurotransmitter) {
        pre_color = get_nt_color();
    }
    else if (color_by_nt_probability) {
       pre_color = viridis(prop_predicted_nt_prob());
    }
    else if (color_by_nt_confidence) {
       pre_color = viridis(prop_nt_tbar_confidence_score());
    }
    else if (color_by_tbar_fanout) {
       float display_fanout = min(float(max_fanout_display), float(prop_tbar_fanout())) / float(max_fanout_display);
       pre_color = viridis(display_fanout);
    }
    else if (color_by_compartment) {
        pre_color = get_compartment_color(int(prop_compartment_pre()));
        post_color = get_compartment_color(int(prop_compartment_post()));
    }
    else if (color_by_neuropil) {
        pre_color = post_color = get_color_for_id(uint(prop_primary_roi()));
    }
    else if (color_by_optic_column) {
        pre_color = post_color = get_color_for_id(uint(prop_optic_column()));
    }
    else if (color_by_optic_layer) {
        pre_color = post_color = get_color_for_id(uint(prop_optic_layer()));
    }
    else if (color_by_neuron_id) {
        pre_color = get_color_for_id(uint(prop_body_pre_u32()));
        post_color = get_color_for_id(uint(prop_body_post_u32()));
    }

    setEndpointMarkerColor(
        vec4(pre_color, 1.0), vec4(post_color, 1.0)
    );

    if (show_pre && show_post) {
        setLineWidth(1.0);
        setEndpointMarkerSize(pre_size, post_size);
    }
    else if (show_post) {
        setLineWidth(0.0);
        setEndpointMarkerSize(0.0, post_size);
    }
    else if (show_pre) {
        setLineWidth(0.0);
        setEndpointMarkerSize(pre_size, 0.0);
    }
    else {
        setLineWidth(0.0);
        setEndpointMarkerSize(0.0, 0.0);
    }
}

